/**
 *
 * OrganizationChartNode is the box for a single node, looked up by `uKey`. It is the
 * `.p-organizationchart-node` element; connectors and nesting are produced by `OrganizationChartNodes`.
 *
 * [Live Demo](https://www.primereact.org/organizationchart/)
 *
 * @module OrganizationChartNode
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { TreeNode } from '@primereact/types/headless/organizationchart';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in OrganizationChartNode component.
 */
export type OrganizationChartNodePassThroughType<E> = PassThroughType<OrganizationChartNodeInstance, E>;
/**
 * Defines passthrough(pt) options of OrganizationChartNode component.
 */
export interface OrganizationChartNodePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: OrganizationChartNodePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in OrganizationChartNode component.
 */
export interface OrganizationChartNodeProps extends BaseComponentProps<OrganizationChartNodeInstance, unknown, OrganizationChartNodePassThrough> {
    /**
     * The unique key identifying this node in the data. Used to resolve node state from the headless layer.
     */
    uKey: string;
}
/**
 * Defines valid state in OrganizationChartNode component.
 */
export interface OrganizationChartNodeState {
}
/**
 * Defines the methods and properties exposed by OrganizationChartNode component.
 */
export interface OrganizationChartNodeExposes {
    /**
     * The resolved node data, or undefined when the key is unknown.
     */
    node: TreeNode | undefined;
    /**
     * Whether the node is expanded (not collapsed).
     */
    expanded: boolean;
    /**
     * Whether the node has no children.
     */
    leaf: boolean;
    /**
     * Whether the node is selected.
     */
    selected: boolean;
}
/**
 * Instance of OrganizationChartNode component.
 */
export type OrganizationChartNodeInstance = ComponentInstance<OrganizationChartNodeProps, OrganizationChartNodeState, OrganizationChartNodeExposes>;
